const {THREE,RAPIER,sim,world,view,root}=game;
const V=THREE.Vector3;
const rockets=[], effects=[];
let cooldown=0,recoil=0,shake=0,clock=0,disposed=false;
const geometries={sphere:new THREE.SphereGeometry(1,12,8),box:new THREE.BoxGeometry(1,1,1),tube:new THREE.CylinderGeometry(.075,.075,.55,12),nose:new THREE.ConeGeometry(.105,.23,12)};
const materials={metal:new THREE.MeshStandardMaterial({color:0x667344,metalness:.55,roughness:.4}),fin:new THREE.MeshStandardMaterial({color:0x353b39}),flame:new THREE.MeshBasicMaterial({color:0xffd36b}),smoke:new THREE.MeshBasicMaterial({color:0x777b79,transparent:true,opacity:.42,depthWrite:false}),blast:new THREE.MeshBasicMaterial({color:0xff841f,transparent:true,opacity:.48,depthWrite:false}),debris:new THREE.MeshStandardMaterial({color:0xb4b4a6,roughness:1})};
const layer=new THREE.Group();layer.name='RPG effects';root.add(layer);
function mesh(geometry,material,parent){const m=new THREE.Mesh(geometry,material);parent.add(m);return m;}
function particle(p,v,size,life,kind,gravity=0){
 if(effects.length>=180){const old=effects.shift();old.mesh.removeFromParent();}
 const m=mesh(kind==='debris'?geometries.box:geometries.sphere,materials[kind],layer);m.position.copy(p);m.scale.setScalar(size);
 effects.push({mesh:m,v:v.clone(),size,life,max:life,kind,gravity});
}
function boxDistance(p,e){const c=e.id==='guard'?{x:sim.guard.x,y:sim.guard.y+.9,z:sim.guard.z}:e.position;return Math.hypot(Math.max(0,Math.abs(p.x-c.x)-e.half.x),Math.max(0,Math.abs(p.y-c.y)-e.half.y),Math.max(0,Math.abs(p.z-c.z)-e.half.z));}
function explode(p){
 const radius=1.25;let broken=0;
 for(const e of game.entities){
  if(e.removed||['ground','near-bank','far-bank','rooftop'].includes(e.id))continue;
  if(boxDistance(p,e)>radius)continue;
  game.removeEntity(e);broken++;
 }
 const away=new V(sim.position.x,sim.position.y,sim.position.z).sub(p),distance=away.length();
 if(distance<3){away.normalize();away.y+=.35;away.normalize().multiplyScalar((1-distance/3)*5);sim.player.applyImpulse({x:away.x,y:away.y,z:away.z},true);}
 particle(p,new V(),.12,.42,'blast');particle(p,new V(),.18,.16,'flame');
 for(let i=0;i<22;i++){const d=new V(Math.random()*2-1,Math.random()*1.7-.3,Math.random()*2-1).normalize().multiplyScalar(2+Math.random()*5);particle(p,d,.05+Math.random()*.1,.65+Math.random()*.55,'debris',9);}
 for(let i=0;i<8;i++)particle(p,new V(Math.random()-.5,.7+Math.random(),Math.random()-.5),.18,.8+Math.random()*.4,'smoke');
 shake=Math.max(shake,Math.max(.015,.09*(1-distance/18)));
 game.sound(75,.32,.13,24);game.say(broken?'BOOM — breach open. Reloading automatically.':'BOOM! Keep some distance from the blast.');
}
function guardHit(origin,dir,length){
 const e=game.entities.find(e=>e.id==='guard'&&!e.removed);
 if(!e||!sim.guardEnabled)return null;
 let near=0,far=length;
 const center={x:sim.guard.x,y:sim.guard.y+.9,z:sim.guard.z};
 for(const axis of ['x','y','z']){
  const lo=center[axis]-e.half[axis],hi=center[axis]+e.half[axis];
  if(Math.abs(dir[axis])<1e-8){if(origin[axis]<lo||origin[axis]>hi)return null;}
  else{let a=(lo-origin[axis])/dir[axis],b=(hi-origin[axis])/dir[axis];if(a>b){const t=a;a=b;b=t;}near=Math.max(near,a);far=Math.min(far,b);if(near>far)return null;}
 }
 return near;
}
function use(){
 if(disposed)return;
 if(cooldown>0){game.say('Reloading — ready in a moment.');return;}
 cooldown=.72;recoil=1;shake=.022;
 const dir=new V(sim.aim.x,sim.aim.y,sim.aim.z);if(dir.lengthSq()<.01)dir.set(1,0,0);dir.normalize();
 const eye=new V(sim.position.x,sim.position.y+.86,sim.position.z);
 const body=new THREE.Group();body.name='flying-rocket';layer.add(body);body.position.copy(eye).addScaledVector(dir,.28);body.quaternion.setFromUnitVectors(new V(0,1,0),dir);
 mesh(geometries.tube,materials.metal,body);
 const nose=mesh(geometries.nose,materials.metal,body);nose.position.y=.36;
 for(let i=0;i<4;i++){const fin=mesh(geometries.box,materials.fin,body);fin.scale.set(.24,.16,.025);fin.position.y=-.2;fin.rotation.y=i*Math.PI/2;}
 const flame=mesh(geometries.sphere,materials.flame,body);flame.position.y=-.44;flame.scale.set(.08,.23,.08);
 rockets.push({body,flame,dir,previous:eye,age:0,trail:0});
 sim.player.applyImpulse({x:-dir.x*.22,y:0,z:-dir.z*.22},true);
 particle(eye.clone().addScaledVector(dir,.7),new V(),.13,.07,'flame');
 game.sound(145,.17,.12,48);game.sound(480,.08,.055,110);game.say('WHOOSH! Rocket away.');
}
function step(dt){
 if(disposed)return;
 clock+=dt;const was=cooldown;cooldown=Math.max(0,cooldown-dt);if(was>0&&cooldown===0)game.sound(620,.045,.045,820);
 recoil=Math.max(0,recoil-dt*5);shake*=Math.exp(-dt*12);
 for(let i=rockets.length-1;i>=0;i--){
  const r=rockets[i];r.age+=dt;
  const end=r.body.position.clone().addScaledVector(r.dir,20*dt),length=end.distanceTo(r.previous);
  const hit=world.castRay(new RAPIER.Ray({x:r.previous.x,y:r.previous.y,z:r.previous.z},{x:r.dir.x,y:r.dir.y,z:r.dir.z}),length,true,undefined,undefined,undefined,sim.player);
  let impact=hit?hit.timeOfImpact:Infinity;
  const gh=guardHit(r.previous,r.dir,length);if(gh!==null)impact=Math.min(impact,gh);
  if(impact<=length){const p=r.previous.clone().addScaledVector(r.dir,impact);explode(p);r.body.removeFromParent();rockets.splice(i,1);continue;}
  r.body.position.copy(end);r.previous.copy(end);r.flame.scale.y=.18+Math.sin(clock*90)*.06;
  r.trail+=dt;if(r.trail>=.035){r.trail=0;particle(end.clone().addScaledVector(r.dir,-.4),r.dir.clone().multiplyScalar(-.45).add(new V(0,.2,0)),.065,.65,'smoke');}
  if(r.age>=4){r.body.removeFromParent();rockets.splice(i,1);}
 }
 for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.life<=0){e.mesh.removeFromParent();effects.splice(i,1);continue;}const t=1-e.life/e.max;e.v.y-=e.gravity*dt;e.mesh.position.addScaledVector(e.v,dt);
  let size=e.size*(1-t);if(e.kind==='smoke')size=e.size*(1+4*t)*(1-t);if(e.kind==='blast')size=1.25*Math.sin(Math.PI*t);if(e.kind==='flame')size=e.size*(1+3*t)*(1-t);
  e.mesh.scale.setScalar(Math.max(.001,size));if(e.kind==='debris'){e.mesh.rotation.x+=dt*7;e.mesh.rotation.z+=dt*4;}
 }
}
const modelBasis=new THREE.Quaternion().setFromAxisAngle(new V(0,1,0),Math.PI/2);
function render(){
 if(disposed)return;
 const camera=game.camera;
 if(view.firstPerson!==false){
  const offset=new V(.32,-.34,-.43+recoil*.14).applyQuaternion(camera.quaternion);
  view.invention.position.copy(camera.position).add(offset);view.invention.quaternion.copy(camera.quaternion).multiply(modelBasis);view.invention.rotateZ(recoil*.075);
 }
 if(shake>.001){camera.position.x+=Math.sin(clock*113)*shake;camera.position.y+=Math.sin(clock*139)*shake*.7;}
}
function dispose(){disposed=true;rockets.length=0;effects.length=0;layer.removeFromParent();layer.clear();for(const g of Object.values(geometries))g.dispose();for(const m of Object.values(materials))m.dispose();}
return {use,step,render,dispose};

