const {sim,world,THREE}=game;
const gate=game.entities.find(e=>e.id==='gate');const wall=game.entities.find(e=>e.id==='wall-right');const other=game.entities.find(e=>e.id==='wall-left');
assert(gate&&wall&&other,'Courtyard contains gate and prison walls');
const flying=()=>{const a=[];game.root.traverse(o=>{if(o.name==='flying-rocket')a.push(o);});return a;};
function aimAt(e){const p=sim.position;const d=new THREE.Vector3(e.position.x-p.x,e.position.y-(p.y+.86),e.position.z-p.z).normalize();sim.aim={x:d.x,y:d.y,z:d.z};}
sim.autoRun=false;sim.manual={x:0,y:0,z:0};sim.player.setTranslation({x:gate.position.x-10,y:.85,z:gate.position.z},true);sim.player.setLinvel({x:0,y:0,z:0},true);advance(2);aimAt(gate);
const gateCollider=gate.collider;
behavior.use();assert(flying().length===1,'Firing creates a visible flying rocket');const initial=flying()[0].position.clone();behavior.use();assert(flying().length===1,'Reload prevents instant duplicate shots');
advance(2);assert(!gate.removed&&gateCollider.isValid(),'Gate survives the early flight frames');assert(flying().length===1&&flying()[0].position.distanceTo(initial)>.5,'Rocket actually travels toward the target');
advance(35);assert(gate.removed&&!gateCollider.isValid(),'Rocket impact removes the gate collider');assert(sim.gateOpen,'Destroyed gate is physically open');assert(!wall.removed&&!other.removed,'Gate blast does not destroy walls outside its radius');
advance(12);sim.player.setTranslation({x:wall.position.x-10,y:.85,z:wall.position.z},true);sim.player.setLinvel({x:0,y:0,z:0},true);advance(2);aimAt(wall);const wallCollider=wall.collider;
behavior.use();assert(flying().length===1,'Launcher fires again after automatic reload');advance(2);assert(!wall.removed,'Second rocket also takes time to reach its target');advance(35);assert(wall.removed&&!wallCollider.isValid(),'Second impact blasts open a prison wall');assert(!other.removed,'Distant prison wall remains intact');assert(game.entities.find(e=>e.id==='ground').collider.isValid(),'Breach leaves walkable ground intact');
